def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest().upper()
def load(name):
    raw=json.loads((RAW/name).read_text(encoding='utf8')); old=json.loads((SEM/name).read_text(encoding='utf8'))
    return raw,old,{int(p['page']):p.get('text','') for p in raw.get('pages',[])}
def spans(pages,a,b): return [{'page':p,'text':pages[p]} for p in range(a,b+1) if p in pages and pages[p].strip()]
def years(t): return sorted({int(x) for x in re.findall(r'\b(?:19|20)\d{2}\b',t)})
def chunk(doc_id,n,title,topic,ctype,tags,sp):
    text='\n\n'.join(x['text'] for x in sp); ys=years(text)
    return {'chunk_id':f'{doc_id}_phase3f_{n:04d}','content_type':ctype,'semantic_tags':sorted(set(tags)),'heading_path':[title],
      'page_start':min(x['page'] for x in sp),'page_end':max(x['page'] for x in sp),'source_spans':sp,'text':text,'keywords':[],'entities':[],
      'temporal_scope':{'primary_year':None,'years_mentioned':ys,'reference_period':{'type':None,'year':None,'semester':None,'quarter':None,'start_date':None,'end_date':None}}}
def sec(doc_id,i,c): return {'section_id':f'{doc_id}_phase3f_sec_{i:03d}','title':c['heading_path'][-1],'topic_id':next((x for x in c['semantic_tags'] if x in TOPICS), 'narrative'),'subsections':[{'subsection_id':f'{doc_id}_phase3f_sec_{i:03d}_sub_01','title':c['heading_path'][-1],'chunks':[c]}]}
