def news_specs(name):
    base=NEWS[name]
    if 'ENG' in name:
        # Same editorial sequence as FR; headings remain source-language labels below.
        return [(a,b,t if not t.startswith('Message') else 'Editorial message',top,ct,tags) for a,b,t,top,ct,tags in base]
    if name.startswith('Akhbar'):
        out=[]
        for a,b,t,top,ct,tags in base:
            # Arabic edition ends earlier and places the two aquaculture interviews earlier.
            if a>=31: continue
            out.append((a,b,t,top,ct,tags))
        out += [(31,32,'ملف تربية الأحياء المائية','aquaculture','statistics',['investment_news','aquaculture','regional_statistics']), (33,35,'حوار مع مدير أكواغو','aquaculture_aquago_interview','faq',['investment_news','aquaculture','interview','faq','investment_opportunity']), (36,39,'حوار مع المديرة العامة للوكالة الوطنية لتنمية تربية الأحياء البحرية','anda_aquaculture_interview','faq',['investment_news','aquaculture','interview','faq']), (40,40,'دليل المصالحة ودليل الخدمات','investment_guide','service',['investment_news','investment_guide','business_support']), (41,43,'مشاريع وشركات مختارة','project_announcement','investment_opportunity',['investment_news','project_announcement','investment_opportunity']), (44,44,'معلومات الاتصال','contact_information','contact_information',['investment_news','contact_information'])]
        return out
    return base

