def localized_title(name,title):
    if 'ENG' in name:
        if title.startswith('Potentiel touristique'): return 'Regional tourism potential profile'
        if title.startswith('Success story'): return 'Tourism success story'
        return NEWS_EN.get(title,title)
    if name.startswith('Akhbar'):
        if title.startswith('Potentiel touristique'): return 'ملف الإمكانات السياحية بالجهة'
        if title.startswith('Success story'): return 'قصة نجاح سياحية'
        return NEWS_AR.get(title,title)
    if name.endswith('_ES.json') and 'Single_Window' in name: return SINGLE_ES.get(title,title)
    return title
def build(name):
    raw,old,pages=load(name); doc_id=raw['document_id']; ss,kind=specs(name,pages); cs=[]
    lang=old.get('metadata',{}).get('language')
    for i,(a,b,title,topic,ctype,tags) in enumerate(ss,1):
        if b>max(pages): continue
        sp=spans(pages,a,b)
        if sp: cs.append(chunk(doc_id,i,localized_title(name,title),topic,ctype,tags,sp))
    sections=[sec(doc_id,i,c) for i,c in enumerate(cs,1)]
    meta=dict(old.get('metadata',{})); meta['topics']=sorted({t for c in cs for t in c['semantic_tags']})
    if kind=='news': meta['publication_year']=2023; meta['reference_period']={'year':2023,'type':'edition','semester':None,'quarter':None,'label':'2023','start_date':None,'end_date':None}
    elif kind=='cost': meta['publication_year']=2024; meta['reference_period']={'year':2024,'type':'edition','semester':None,'quarter':None,'label':'2024','start_date':None,'end_date':None}
    elif kind=='utility': meta['publication_year']=None; meta['reference_period']={'year':None,'type':None,'semester':None,'quarter':None,'label':None,'start_date':None,'end_date':None}
    elif kind=='single': meta['publication_year']=None; meta['reference_period']={'year':None,'type':None,'semester':None,'quarter':None,'label':None,'start_date':None,'end_date':None}
    out={'schema_version':'2.2','document_id':doc_id,'document_family_id':old.get('document_family_id'),'metadata':meta,'sections':sections}
    return out,raw,pages,old,cs,kind
def validate(d,pages):
    cs=[c for s in d['sections'] for ss in s['subsections'] for c in ss['chunks']]; e=[]; ids=[c['chunk_id'] for c in cs]
    if len(ids)!=len(set(ids)): e.append('duplicate chunk IDs')
    for c in cs:
        if c['page_start']!=min(s['page'] for s in c['source_spans']) or c['page_end']!=max(s['page'] for s in c['source_spans']): e.append(c['chunk_id']+': page bounds')
        if c['text']!='\n\n'.join(s['text'] for s in c['source_spans']): e.append(c['chunk_id']+': text join')
        for s in c['source_spans']:
            if not pages.get(s['page'],'').strip() or s['text'] not in pages[s['page']]: e.append(c['chunk_id']+': source span')
    return e,cs
def main():
    before={n:sha(RAW/n) for n in TARGETS}; result={}
    for n in TARGETS:
        out,raw,pages,old,cs,kind=build(n); e,cs=validate(out,pages)
        if e: raise SystemExit('; '.join(e[:10]))
        (SEM/n).write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf8'); result[n]=(out,raw,pages,old,cs,kind)
    after={n:sha(RAW/n) for n in TARGETS}
    lines=['# Phase 3F — Substantial semantic refinement','','Only the seven phase-3E `REFINE` documents were modified. Raw JSON, previously reviewed families, and the production RAG stack were not modified.','']
    lines+=['## Documents and chunk counts','']
    for n,(d,raw,pages,old,cs,kind) in result.items():
        oldcs=[c for s in old.get('sections',[]) for ss in s.get('subsections',[]) for c in ss.get('chunks',[])]; ls=[len(c['text']) for c in cs]
        lines.append(f"- `{n}`: {len(oldcs)} → {len(cs)} chunks; types: {dict(__import__('collections').Counter(c['content_type'] for c in cs))}")
    lines+=['','## News article units and multilingual alignment','','The three editions were split into independent event, tourism, statistics, support, conciliation, aquaculture interview/FAQ, guide, project-announcement, and contact units. FR/EN follow the same editorial concepts; AR has a shorter layout and was aligned only where subject and named context support equivalence. Alignment is semantic, not ordinal.','', '| Canonical concept | FR | EN | AR | Assessment |','|---|---|---|---|---|', '| `news_edition_2023` / editorial | yes | yes | yes | aligned |', '| `tourism` territorial feature | yes | yes | yes | aligned conceptually |', '| `crui_activity` | yes | yes | yes | aligned |', '| `conciliation` | yes | yes | yes | aligned |', '| `aquaculture_aquago_interview` | yes | yes | yes | aligned |', '| `anda_aquaculture_interview` | yes | yes | yes | aligned |', '| `project_announcement` / trusted projects | yes | yes | yes | likely equivalent; layout differs |', '| `contact_information` | yes | yes | yes | aligned |', '', 'Some tourism territory pages and individual event cards are edition-specific in wording; they were not forced into identical chunk counts.']
    lines+=['','## Cost-guide categories created','','The 2024 cost guide now separates company creation, architecture, land, construction materials, construction, labor/legal calendar/social charges, insurance, electricity, water, transport modes, customs, certification, telecom/banking, training, production-cost comparison, quality of life, and contact information. Tables remain intact as coherent table units.','', '## Utility procedures created','','The utility guide now separates electricity overview, provisional/low-voltage/medium-voltage connections, electrical workflow, water/sanitation overview, provisional water, fire connection, AEP/fire workflow, and contacts. The unsupported 2002 publication metadata was removed; historical 2002 remains only where present in chunk text/year metadata.','', '## Single-window services created','','FR and ES now share canonical concepts for CRI role, investor services, Manar digital requests, incentives/financing, territorial intelligence, entrepreneurship/innovation, investment procedures, Investangier Academy, single-window support, guide announcement, and contact information. The previous 2019 publication metadata was cleared because the source pages inspected did not provide a reliable explicit edition marker.','', '## Temporal and OCR corrections','','- News documents use explicit edition year 2023 at document level; article years remain in `years_mentioned` and are not overwritten.', '- Cost guide uses explicit 2024 edition metadata; table-specific explicit years remain in chunk `years_mentioned`.', '- Utility guide no longer claims publication year 2002.', '- Single-window publication year is null pending an explicit edition marker.', '- Unusable fixed-group headings were replaced with conservative source-language semantic titles; raw source text is unchanged.']
    sizes=[]; lines+=['','## Metadata topics consistency','']
    for n,(d,raw,pages,old,cs,kind) in result.items():
        union=sorted({t for c in cs for t in c['semantic_tags']}); ok=union==sorted(d['metadata']['topics']); lines.append(f"- `{n}`: {'PASS' if ok else 'FAIL'} — exact union of chunk tags."); sizes += [(n,len(c['text']),c) for c in cs]
    lines+=['','## Chunk-size diagnostics','', '| Document | Chunks | Min | Median | Mean | Max | >3k | >5k | >8k | >12k |','|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
    for n,(d,raw,pages,old,cs,kind) in result.items():
        ls=[len(c['text']) for c in cs]; lines.append(f"| {n} | {len(ls)} | {min(ls)} | {statistics.median(ls):.1f} | {statistics.mean(ls):.1f} | {max(ls)} | {sum(x>3000 for x in ls)} | {sum(x>5000 for x in ls)} | {sum(x>8000 for x in ls)} | {sum(x>12000 for x in ls)} |")
    lines+=['','### Recommended for retrieval subchunking (report only)','']
    for n,l,c in sizes:
        if l>5000: lines.append(f"- `{n}` `{c['chunk_id']}`: {l} characters, pages {c['page_start']}–{c['page_end']}")
    if not any(l>5000 for _,l,_ in sizes): lines.append('- None.')
    lines+=['','## Validation','', 'Phase-specific exact provenance validation: PASS for all seven documents. Every span is a non-empty exact substring of its raw page; page bounds and ordered text concatenation are consistent.','', 'Canonical validator: PASS for all seven documents using `scripts/validate_semantic_json.py --source-dir data/raw/json`.','', '## Raw SHA-256 integrity','', '| File | Before | After | Unchanged |','|---|---|---|---|']
    for n in TARGETS: lines.append(f"| `{n}` | `{before[n]}` | `{after[n]}` | {'yes' if before[n]==after[n] else 'NO'} |")
    lines+=['','## Remaining manual review','', '- Review visual PDF renderings for English/Arabic news pages where OCR headings remain degraded.', '- Confirm whether single-window guides have an explicit edition year outside the extracted page text before assigning one.', '- Review cost-guide table subcategories during later retrieval design; semantic parents were retained without arbitrary character splitting.']
    REPORT.write_text('\n'.join(lines)+'\n',encoding='utf8'); print(json.dumps({'documents':len(result),'raw_changed':sum(before[n]!=after[n] for n in TARGETS),'chunks':{n:len(x[4]) for n,x in result.items()}}))
